    void call(String action,JSONObject args,Done done,Button sending){
        String auth=token;if(sending!=null)sending.setEnabled(false);if(progress!=null)progress.setVisibility(View.VISIBLE);
        io.execute(()->{try{JSONObject result=api.call(action,args,auth);main.post(()->{if(isDestroyed()||!auth.equals(token))return;if(progress!=null)progress.setVisibility(View.GONE);if(sending!=null)sending.setEnabled(true);done.accept(result);});}
        catch(Exception ex){main.post(()->{if(isDestroyed()||!auth.equals(token))return;if(progress!=null)progress.setVisibility(View.GONE);if(sending!=null)sending.setEnabled(true);if(ex instanceof ParentApi.Failure&&((ParentApi.Failure)ex).unauthorized){recoverSession();}else error(ex);});}});
    }
    void login(boolean phone){
        pendingLoginCard="";epoch++;base("",false);body.removeAllViews();
        LinearLayout intro=row(this);intro.setGravity(Gravity.CENTER_VERTICAL);
        LinearLayout words=column(this);words.addView(chip(this,"LEBIH DEKAT DENGAN ANANDA",BLUE,0xFFEEF0FE));gap(words,12);
        words.addView(text(this,"Setiap langkah,\nselalu terhubung.",26,INK,true));gap(words,8);
        words.addView(text(this,"Ikuti kabar sekolah dan perjalanan belajar ananda.",13,MUTED,false));
        intro.addView(words,new LinearLayout.LayoutParams(0,-2,1));
        intro.setBackground(surface(this,0xFFEEF0FE,22));pad(intro,20);add(intro);
        LinearLayout c=Ui.card(this);pad(c,22);add(c);
        c.addView(text(this,"Portal Wali Murid",23,INK,true));gap(c,4);c.addView(text(this,"Pantau aktivitas ananda dengan mudah",13,MUTED,false));gap(c,20);
        LinearLayout methods=row(this);methods.setBackground(bg(this,BG,14));pad(methods,4);
        Button byCard=button(this,"Kartu siswa",!phone,()->login(false)),byPhone=button(this,"WhatsApp",phone,()->login(true));
        LinearLayout.LayoutParams cardTab=new LinearLayout.LayoutParams(0,dp(this,48),1);cardTab.rightMargin=dp(this,6);methods.addView(byCard,cardTab);methods.addView(byPhone,new LinearLayout.LayoutParams(0,dp(this,48),1));c.addView(methods);gap(c,20);
        c.addView(text(this,phone?"Nomor WhatsApp":"Nomor kartu identitas siswa",13,INK,true));gap(c,8);
        EditText entry=input(this,phone?"Contoh: 081234567890":"16 digit nomor kartu",InputType.TYPE_CLASS_PHONE);
        if(!phone)entry.setFilters(new InputFilter[]{new InputFilter.LengthFilter(16)});
        entry.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_GO);c.addView(entry);gap(c,8);
        c.addView(text(this,phone?"Gunakan nomor yang terdaftar di sekolah. Kode OTP akan dikirim melalui WhatsApp.":"Nomor tercetak pada kartu pelajar ananda. Jaga kerahasiaan nomor kartu Anda.",12,MUTED,false));
        Button submit=button(this,phone?"Kirim kode verifikasi  →":"Masuk ke portal  →",true,()->{});
        submit.setOnClickListener(v->{String value=entry.getText().toString().replaceAll("[^0-9]","");if((!phone&&value.length()!=16)||(phone&&(value.length()<10||value.length()>15))){entry.setError(phone?"Periksa nomor WhatsApp":"Masukkan 16 digit kartu");entry.requestFocus();return;}
            ((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(entry.getWindowToken(),0);
            if(phone)call("request_otp",j("phone",value),r->{otpPhone=s(r,"phone");otp();},submit);
            else {pendingLoginCard=value;call("login_card",j("card_number",value),this::authenticated,submit);}
        });entry.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_GO){if(submit.isEnabled())submit.performClick();return true;}return false;});
        gap(c,20);c.addView(submit,new LinearLayout.LayoutParams(-1,dp(this,48)));
        gap(c,18);LinearLayout secure=row(this);secure.addView(new Glyph(this,"check",0xFF15977D),new LinearLayout.LayoutParams(dp(this,18),dp(this,18)));TextView note=text(this,"  Akses khusus orang tua / wali terdaftar",11,MUTED,false);secure.addView(note,new LinearLayout.LayoutParams(0,-2,1));c.addView(secure);
        LinearLayout features=row(this);String[] labels={"Kehadiran","Tagihan SPP","Kartu digital"},icons={"check","wallet","card"};for(int i=0;i<3;i++){LinearLayout item=column(this);item.setGravity(Gravity.CENTER);item.addView(iconTile(this,icons[i],BLUE,0xFFEEF0FE,40),new LinearLayout.LayoutParams(dp(this,40),dp(this,40)));gap(item,6);TextView featureLabel=text(this,labels[i],11,MUTED,false);featureLabel.setGravity(Gravity.CENTER);item.addView(featureLabel);features.addView(item,new LinearLayout.LayoutParams(0,-2,1));}add(features);
        TextView help=text(this,"Kesulitan masuk? Hubungi admin sekolah",12,BLUE,true);help.setGravity(Gravity.CENTER);help.setPadding(0,dp(this,14),0,dp(this,14));help.setOnClickListener(v->alert("Bantuan masuk","Pastikan nomor kartu berisi 16 digit atau gunakan WhatsApp yang terdaftar. Jika data belum ditemukan, hubungi admin sekolah untuk memperbarui data wali murid."));add(help);
        TextView privacyLink=text(this,"Privasi  •  Informasi layanan",12,BLUE,true);privacyLink.setGravity(Gravity.CENTER);privacyLink.setPadding(dp(this,12),dp(this,14),dp(this,12),dp(this,14));privacyLink.setMinHeight(dp(this,48));privacyLink.setOnClickListener(v->privacy());add(privacyLink);TextView footer=text(this,"ATSkolla Parent\nPlatform digital sekolah",11,MUTED,false);footer.setGravity(Gravity.CENTER);footer.setLineSpacing(dp(this,4),1);footer.setPadding(0,dp(this,8),0,dp(this,20));add(footer);
    }
    void otp(){
        int generation=++epoch;base("Verifikasi WhatsApp",false);
        LinearLayout c=card("Cek WhatsApp Anda","Masukkan 6 digit kode yang dikirim ke "+otpPhone+".");
        gap(c,20);EditText code=input(this,"• • • • • •",InputType.TYPE_CLASS_NUMBER);code.setTextSize(26);code.setLetterSpacing(.25f);code.setGravity(Gravity.CENTER);code.setFilters(new InputFilter[]{new InputFilter.LengthFilter(6)});c.addView(code);
        Button verify=button(this,"Verifikasi dan masuk  →",true,()->{});verify.setOnClickListener(v->{String value=code.getText().toString();if(value.length()!=6){code.setError("Masukkan 6 digit kode");return;}call("verify_otp",j("phone",otpPhone,"otp",value),this::authenticated,verify);});gap(c,16);c.addView(verify,new LinearLayout.LayoutParams(-1,dp(this,48)));
        label(c,"Jangan bagikan kode ini kepada siapa pun, termasuk pihak yang mengatasnamakan sekolah.");
        action(c,"Ganti nomor WhatsApp",false,()->login(true));
        Button resend=button(this,"Kirim ulang kode",false,()->{});resend.setOnClickListener(v->call("request_otp",j("phone",otpPhone),r->{otpPhone=s(r,"phone");otp();},resend));add(resend);
        long availableAt=SystemClock.elapsedRealtime()+60000;main.post(new Runnable(){public void run(){if(generation!=epoch||isDestroyed())return;long remaining=Math.max(0,(availableAt-SystemClock.elapsedRealtime()+999)/1000);resend.setEnabled(remaining==0);resend.setText(remaining>0?"Kirim ulang dalam "+remaining+" detik":"Kirim ulang kode");if(remaining>0)main.postDelayed(this,1000);}});
    }
