    JSONArray invoiceRows(JSONObject d){JSONArray rows=arr(d,"invoices");if(rows.length()>0)return rows;JSONArray merged=new JSONArray();for(String key:new String[]{"aktif","lunas"}){JSONArray source=arr(d,key);for(int i=0;i<source.length();i++)merged.put(source.opt(i));}return merged;}
    boolean payable(JSONObject invoice){return Arrays.asList("pending","unpaid","expired","failed","partial").contains(s(invoice,"status"));}
    double remaining(JSONObject invoice){return Math.max(0,number(invoice,"total_amount")-number(invoice,"installment_paid_amount"));}
    void invoices(JSONObject d,boolean cached){
        JSONArray rows=invoiceRows(d);double due=0;int unpaid=0;for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(payable(r)){due+=remaining(r);unpaid++;}}
        LinearLayout panel=Ui.card(this);section(panel,"Pembayaran SPP & Tagihan","wallet");LinearLayout total=column(this);pad(total,20);total.setBackground(gradient(this,due>0?0xFFF6414A:0xFF10B991,due>0?0xFFE5174C:0xFF068A80,22));total.addView(text(this,due>0?"TOTAL TAGIHAN BELUM LUNAS":"TAGIHAN ANANDA",11,0xFFFFE5ED,true));gap(total,7);total.addView(text(this,rupiah(due),30,Color.WHITE,true));total.addView(text(this,unpaid+" tagihan belum lunas",14,Color.WHITE,true));panel.addView(total);if(cached){gap(panel,8);panel.addView(text(this,"Data tersimpan. Tombol bayar aktif setelah pemeriksaan terbaru selesai.",12,MUTED,false));}add(panel);
        boolean firstActive=true,firstHistory=true;int shown=0;for(int group=0;group<2;group++){for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);boolean active=payable(r),paid="paid".equals(s(r,"status"));if((group==0)!=active)continue;if(active&&firstActive){section("Tagihan Aktif","wallet");firstActive=false;}if(!active&&firstHistory){section("Riwayat Tagihan","check");firstHistory=false;}if(shown++>=visibleRows)continue;
            boolean expired="expired".equals(s(r,"status"));int accent=paid?0xFF08A980:expired?0xFFFA780E:BLUE;LinearLayout bill=Ui.card(this);bill.setBackground(surface(this,paid?0xFFE8F8F0:expired?0xFFFFEFE0:0xFFEEEFFF,22));pad(bill,18);LinearLayout title=row(this);title.setGravity(Gravity.TOP);String name=s(r,"period_label");if(name.isEmpty())name=s(r,"invoice_number");TextView nameText=text(this,name,17,INK,true);title.addView(nameText,new LinearLayout.LayoutParams(0,-2,1));String state=paid?"Lunas":expired?"Kadaluarsa":"partial".equals(s(r,"status"))?"Dicicil":active?"Belum lunas":s(r,"status");TextView badge=pill(state,Color.WHITE,accent);LinearLayout.LayoutParams badgeSize=new LinearLayout.LayoutParams(-2,-2);badgeSize.leftMargin=dp(this,8);title.addView(badge,badgeSize);bill.addView(title);gap(bill,5);TextView reference=text(this,s(r,"invoice_number"),11,MUTED,false);reference.setMaxLines(2);reference.setEllipsize(android.text.TextUtils.TruncateAt.END);bill.addView(reference);gap(bill,15);bill.addView(text(this,rupiah(number(r,"total_amount")),25,paid?0xFF08A980:BLUE,true));gap(bill,5);bill.addView(text(this,"Jatuh tempo: "+date(s(r,"due_date")),12,MUTED,false));double partial=number(r,"installment_paid_amount");if(partial>0){gap(bill,8);bill.addView(text(this,"Sudah dicicil: "+rupiah(partial)+"\nSisa: "+rupiah(remaining(r)),13,accent,true));}
            if(paid){gap(bill,8);bill.addView(text(this,"Dibayar "+date(s(r,"paid_at")),12,0xFF088F73,true));action(bill,"Unduh Bukti Pembayaran PDF",false,()->invoicePdf(r));if(s(r,"id").equals(pendingPayment)){pendingPayment="";toast("Pembayaran telah tervalidasi oleh sekolah");}}
            else if(active){if(r.optBoolean("allow_installment")&&!"spp".equals(s(r,"bill_type"))){gap(bill,12);bill.addView(text(this,"Tagihan bisa dibayar Cicil / Lunas",12,BLUE,true));}gap(bill,12);Button pay=colorButton(this,expired?"Buat Link Baru & Bayar":"Bayar Tagihan",expired?0xFFFF7411:BLUE,expired?0xFFF05200:0xFF4C5DED,()->payment(r,0));pay.setEnabled(!cached);bill.addView(pay,new LinearLayout.LayoutParams(-1,dp(this,48)));if(r.optBoolean("allow_installment")&&!"spp".equals(s(r,"bill_type")))action(bill,"Cicilan & Riwayat",false,()->installments(r));action(bill,"Rincian Tagihan PDF",false,()->invoicePdf(r));}
            add(bill);
        }}if(rows.length()==0){LinearLayout empty=Ui.card(this);empty(empty,"Belum ada tagihan dari sekolah.");add(empty);}if(rows.length()>visibleRows)add(button(this,"Tampilkan lebih banyak",false,()->{visibleRows+=40;load(false);}));
        if(!pendingPayment.isEmpty()&&!cached&&paymentChecks<8&&foreground){main.removeCallbacks(paymentPoll);main.postDelayed(paymentPoll,20000);}
    }
    final Runnable paymentPoll=()->{if(foreground&&screen.equals("spp")&&!pendingPayment.isEmpty()&&paymentChecks++<8)load(true);};
    void installments(JSONObject invoice){call("installment_list",j("student_id",studentId,"invoice_id",s(invoice,"id")),r->{epoch++;base("Cicilan tagihan",true);LinearLayout summary=card(s(invoice,"period_label"),s(invoice,"invoice_number"));label(summary,"Lunas: "+rupiah(number(r,"paid_amount")));label(summary,"Menunggu pembayaran: "+rupiah(number(r,"pending_amount")));label(summary,"Dapat dicicil: "+rupiah(number(r,"remaining")));if(number(r,"remaining")>0){EditText amount=input(this,"Nominal cicilan (Rp)",InputType.TYPE_CLASS_NUMBER);add(amount);Button create=button(this,"Pilih metode pembayaran",true,()->{try{long value=Long.parseLong(amount.getText().toString());if(value<1000||value>number(r,"remaining")){amount.setError("Masukkan nominal Rp1.000 hingga sisa tagihan");return;}payment(invoice,value);}catch(Exception e){amount.setError("Masukkan nominal cicilan");}});add(create);}list(arr(r,"installments"),row->{LinearLayout c=card(rupiah(number(row,"amount")),date(s(row,"created_at")));badge(c,s(row,"status"));if("pending".equals(s(row,"status"))&&!s(row,"mayar_payment_url").isEmpty())action(c,"Lanjutkan pembayaran",false,()->{pendingPayment=s(invoice,"id");paymentChecks=0;open(s(row,"mayar_payment_url"));});});},null);}
    void payment(JSONObject invoice,long amount){if(preparingPayment)return;preparingPayment=true;call("payment_config",j(),cfg->{preparingPayment=false;String[] channels={"qris","va","retail"};JSONObject fees=obj(cfg,"fees");double bill=amount>0?amount:Math.max(0,number(invoice,"total_amount")-number(invoice,"installment_paid_amount"));String[] choices={"QRIS","Virtual account / transfer bank","Retail / minimarket"};new AlertDialog.Builder(this).setTitle("Pilih metode pembayaran").setItems(choices,(dialog,index)->{String channel=channels[index];double estimate=channel.equals("qris")?Math.max(fees.optDouble("qris",3000),Math.round(bill*cfg.optDouble("qris_percent",0.01))):number(fees,channel);new AlertDialog.Builder(this).setTitle(choices[index]).setMessage("Tagihan: "+rupiah(bill)+"\nPerkiraan biaya layanan: "+rupiah(estimate)+"\n\nBiaya akhir akan ditampilkan sebelum melanjutkan ke penyedia pembayaran.").setNegativeButton("Batal",null).setPositiveButton("Buat pembayaran",(d,w)->{if(preparingPayment)return;preparingPayment=true;JSONObject args=j("student_id",studentId,"invoice_id",s(invoice,"id"),"channel",channel);String action="spp_pay";if(amount>0){action="spp_pay_installment";try{args.put("amount",amount);}catch(Exception ignored){}}call(action,args,result->{preparingPayment=false;String url=s(result,"payment_url");if(url.isEmpty()){alert("Belum dapat membayar","Tautan pembayaran tidak tersedia.");return;}double actual=number(result,"total_charged");new AlertDialog.Builder(this).setTitle("Pembayaran siap").setMessage("Total: "+rupiah(actual)+"\nBiaya layanan: "+rupiah(number(result,"service_fee"))+"\n\nAnda akan melanjutkan ke halaman resmi pembayaran melalui browser. Status lunas hanya mengikuti konfirmasi server.").setNegativeButton("Nanti",null).setPositiveButton("Lanjut pembayaran",(confirm,which)->{pendingPayment=s(invoice,"id");paymentChecks=0;screen="spp";open(url);}).show();},null);}).show();}).show();},null);}
    String formattedCard(String value){return value.isEmpty()?"Belum diterbitkan":value.replaceAll("(.{4})(?!$)","$1 ");}
    Bitmap studentQr(JSONObject student,int size) throws Exception {String value=s(student,"qr_code");if(value.isEmpty())value=s(student,"student_id");if(value.isEmpty())value=s(student,"id");if(value.isEmpty())throw new IOException("Identitas QR belum tersedia");Map<EncodeHintType,Object> hints=new EnumMap<>(EncodeHintType.class);hints.put(EncodeHintType.MARGIN,4);hints.put(EncodeHintType.CHARACTER_SET,"UTF-8");hints.put(EncodeHintType.ERROR_CORRECTION,com.google.zxing.qrcode.decoder.ErrorCorrectionLevel.Q);BitMatrix matrix=new MultiFormatWriter().encode(value,BarcodeFormat.QR_CODE,size,size,hints);Bitmap bitmap=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);int[] pixels=new int[size*size];for(int y=0;y<size;y++)for(int x=0;x<size;x++)pixels[y*size+x]=matrix.get(x,y)?0xFF0F172A:Color.WHITE;bitmap.setPixels(pixels,0,size,0,0,size,size);return bitmap;}
    void savePng(Bitmap bitmap,String filename){try{ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,out);export(out.toByteArray(),"image/png",filename);}catch(Exception e){error(e);}}
