        LinearLayout numberBox=column(this);pad(numberBox,12);numberBox.setBackground(bg(this,0x33000000,14));numberBox.addView(text(this,"NOMOR KARTU IDENTITAS",9,0xFFD9DEFF,true));TextView number=text(this,formattedCard(s(student,"card_number")),16,Color.WHITE,true);number.setTypeface(Typeface.MONOSPACE);numberBox.addView(number);card.addView(numberBox);gap(card,18);
        try{Bitmap qr=studentQr(student,768);ImageView code=new ImageView(this);code.setImageBitmap(qr);code.setBackground(bg(this,Color.WHITE,14));code.setClipToOutline(true);code.setContentDescription("Kode QR siswa. Ketuk untuk memperbesar");LinearLayout.LayoutParams qrSize=new LinearLayout.LayoutParams(dp(this,184),dp(this,184));qrSize.gravity=Gravity.CENTER_HORIZONTAL;card.addView(code,qrSize);code.setOnClickListener(v->{ImageView enlarged=new ImageView(this);enlarged.setImageBitmap(qr);enlarged.setAdjustViewBounds(true);pad(enlarged,12);new AlertDialog.Builder(this).setTitle("QR "+s(student,"name")).setView(enlarged).setPositiveButton("Tutup",null).show();});gap(card,12);TextView scan=text(this,"SCAN UNTUK VERIFIKASI",9,0xFFE7E9FF,true);scan.setGravity(Gravity.CENTER);card.addView(scan);
            FrameLayout holder=new FrameLayout(this);FrameLayout.LayoutParams dimensions=new FrameLayout.LayoutParams(-1,-2,Gravity.TOP|Gravity.CENTER_HORIZONTAL);holder.addView(card,dimensions);holder.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{int desired=Math.min(holder.getWidth(),dp(this,360));if(card.getLayoutParams().width!=desired){FrameLayout.LayoutParams params=(FrameLayout.LayoutParams)card.getLayoutParams();params.width=desired;card.setLayoutParams(params);}});add(holder);
            gap(card,5);TextView powered=text(this,"Powered by ATSkolla",10,0xFFBFC5F3,false);powered.setGravity(Gravity.CENTER);card.addView(powered);
            LinearLayout actions=row(this);Button downloadQr=button(this,"Unduh QR",false,()->savePng(qr,"QR-ATSkolla.png"));Button downloadCard=button(this,"Unduh kartu",true,()->{try{if(card.getWidth()==0)return;float scale=1080f/card.getWidth();Bitmap bitmap=Bitmap.createBitmap(1080,Math.round(card.getHeight()*scale),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.scale(scale,scale);card.draw(canvas);savePng(bitmap,"Kartu-ATSkolla.png");bitmap.recycle();}catch(Exception e){error(e);}});LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,dp(this,48),1);left.rightMargin=dp(this,8);actions.addView(downloadQr,left);actions.addView(downloadCard,new LinearLayout.LayoutParams(0,dp(this,48),1));add(actions);
        }catch(Exception e){add(card);label(card,"QR belum tersedia. Hubungi admin sekolah.");}
