    static List<String> wrap(String text,Paint p,int width){List<String> lines=new ArrayList<>();StringBuilder current=new StringBuilder();for(String word:text.split(" ")){if(p.measureText(current+" "+word)>width&&current.length()>0){lines.add(current.toString());current.setLength(0);}if(current.length()>0)current.append(' ');current.append(word);}lines.add(current.toString());return lines;}
    void export(byte[] data,String mime,String filename){pendingDocument=data;Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT);save.addCategory(Intent.CATEGORY_OPENABLE);save.setType(mime);save.putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(save,700);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){if(request==700)pendingDocument=null;return;}Uri uri=data.getData();if(request==700&&pendingDocument!=null){byte[] bytes=pendingDocument;pendingDocument=null;io.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Tidak dapat menyimpan berkas");out.write(bytes);main.post(()->toast("Berkas berhasil disimpan"));}catch(Exception e){main.post(()->error(e));}});}else if(request==701){final int generation=epoch;final String auth=token;final String mime=getContentResolver().getType(uri);if(!Arrays.asList("image/jpeg","image/png","image/webp","application/pdf").contains(mime)){toast("Pilih JPG, PNG, WebP atau PDF");return;}attachmentUploading=true;if(leaveAttachment!=null)leaveAttachment.setEnabled(false);if(leaveSubmit!=null)leaveSubmit.setEnabled(false);if(attachmentLabel!=null)attachmentLabel.setText("Mengunggah lampiran…");io.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Berkas tidak dapat dibuka");ByteArrayOutputStream buffer=new ByteArrayOutputStream();byte[] part=new byte[8192];int n;while((n=in.read(part))!=-1){if(buffer.size()+n>5*1024*1024)throw new IOException("Lampiran maksimal 5 MB");buffer.write(part,0,n);}String ext=mime.equals("application/pdf")?".pdf":mime.equals("image/png")?".png":mime.equals("image/webp")?".webp":".jpg";String url=api.upload(buffer.toByteArray(),mime,ext,auth);main.post(()->{if(generation!=epoch||!auth.equals(token))return;attachmentUploading=false;if(leaveAttachment!=null)leaveAttachment.setEnabled(true);if(leaveSubmit!=null)leaveSubmit.setEnabled(true);attachment=url;if(attachmentLabel!=null)attachmentLabel.setText("Lampiran berhasil diunggah");});}catch(Exception e){main.post(()->{if(generation==epoch){attachmentUploading=false;if(leaveAttachment!=null)leaveAttachment.setEnabled(true);if(leaveSubmit!=null)leaveSubmit.setEnabled(true);if(attachmentLabel!=null)attachmentLabel.setText("Lampiran belum terunggah");error(e);}});}});}}
    void open(String url){try{Uri uri=Uri.parse(url);if(!Arrays.asList("https","tel","mailto").contains(uri.getScheme())){toast("Tautan tidak didukung");return;}startActivity(new Intent(Intent.ACTION_VIEW,uri).addCategory(Intent.CATEGORY_BROWSABLE));}catch(ActivityNotFoundException e){toast("Aplikasi untuk membuka tautan belum tersedia");}}
