    void routeNotification(Intent intent){if(intent==null)return;boolean attendance=intent.getBooleanExtra("open_attendance",false),announcements=intent.getBooleanExtra("open_announcements",false);if(!attendance&&!announcements)return;screen=attendance?"attendance":"info";String selected=intent.getStringExtra("student_id");if(selected!=null)studentId=selected;if(attendance){String date=intent.getStringExtra("attendance_date");try{LocalDate.parse(date);from=date;to=date;}catch(Exception ignored){}}}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);routeNotification(intent);if(!token.isEmpty()){selectValidStudent();load(true);}else login(false);}
    void recoverSession(){
        if(renewingSession||token.isEmpty())return;
        if(vault.get("remembered_card").isEmpty()){clearSession();login(false);toast("Sesi perlu diperbarui. Silakan masuk kembali.");return;}
        renewingSession=true;String previous=token;if(status!=null)status.setText("Memulihkan sesi tersimpan…");
        io.execute(()->{try{String next=ParentSessions.renew(this,api,previous);main.post(()->{renewingSession=false;if(isDestroyed()||!previous.equals(token))return;if(next.isEmpty()){clearSession();login(false);return;}token=next;bootstrap();});}catch(Exception e){main.post(()->{renewingSession=false;if(isDestroyed()||!previous.equals(token))return;if(e instanceof ParentApi.Failure){clearSession();login(false);toast("Akun perlu diverifikasi kembali oleh sekolah.");}else error(e);});}});
    }
    void offerNotifications(){if(preview()||!vault.get("notifications_prompted").isEmpty())return;try{vault.put("notifications_prompted","yes");}catch(Exception ignored){}notificationSettings();}
    void notificationSettings(){new AlertDialog.Builder(this).setTitle("Notifikasi Datang & Pulang")
        .setMessage("Dapatkan notifikasi Android saat data absensi Datang/Pulang siswa yang terhubung berubah, dari semua metode absensi, serta pengumuman sekolah.\n\nPemeriksaan sekitar 30 detik saat aplikasi terbuka. Di latar belakang Android mengatur pemeriksaan sekitar 15 menit atau lebih, sehingga notifikasi dapat terlambat. Ini belum push instan.\n\nAplikasi meminta izin notifikasi. Di layar terkunci, detail siswa disembunyikan. Anda dapat menonaktifkannya kapan saja.")
        .setNegativeButton("Nanti",null)
        .setNeutralButton("Nonaktifkan",(d,w)->{ParentNotificationJob.disable(this);toast("Notifikasi dinonaktifkan");})
        .setPositiveButton("Aktifkan",(d,w)->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},810);else enableAnnouncements();}).show();}
    void enableAnnouncements(){try{if(!ParentNotificationJob.allowed(this)){toast("Izinkan notifikasi ATSkolla melalui pengaturan Android.");startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));return;}ParentNotificationJob.enable(this);toast("Notifikasi absensi dan pengumuman diaktifkan");checkNotifications();}catch(Exception e){error(e);}}
    void checkNotifications(){if(preview()||token.isEmpty()||!ParentNotificationJob.enabled(this)||!ParentNotificationJob.allowed(this))return;String auth=token;io.execute(()->{try{ParentNotifications.check(this,false);}catch(ParentApi.Failure e){if(e.unauthorized)main.post(()->{if(!isDestroyed()&&auth.equals(token))recoverSession();});}catch(Exception ignored){/* Retry next scheduled check without interrupting the current form. */}});}
    private final Runnable notificationCheck=new Runnable(){public void run(){if(!foreground)return;checkNotifications();main.postDelayed(this,30000);}};
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==810){if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)enableAnnouncements();else toast("Notifikasi belum diizinkan. Anda tetap dapat melihat absensi di aplikasi.");}}
    private final Runnable foregroundRefresh=new Runnable(){public void run(){if(foreground&&!token.isEmpty()&&Arrays.asList("home","info").contains(screen)){int position=scroll==null?0:scroll.getScrollY();load(true);if(scroll!=null)scroll.post(()->scroll.scrollTo(0,position));}if(foreground)main.postDelayed(this,60000);}};
    @Override protected void onResume(){super.onResume();foreground=true;ParentNotifications.foreground=true;if(vault!=null&&!token.isEmpty()){String saved=vault.get("token");if(!saved.isEmpty())token=saved;}main.removeCallbacks(notificationCheck);main.postDelayed(notificationCheck,1000);main.removeCallbacks(foregroundRefresh);main.postDelayed(foregroundRefresh,60000);ParentNotificationJob.schedule(this);if(!pendingPayment.isEmpty()&&!token.isEmpty()){screen="spp";paymentChecks=0;load(true);}}
    @Override protected void onPause(){foreground=false;ParentNotifications.foreground=false;main.removeCallbacks(notificationCheck);main.removeCallbacks(foregroundRefresh);main.removeCallbacks(paymentPoll);super.onPause();}
